// DocumentosComponent
ngOnInit(): void {
  this.documentoService.listar().subscribe(docs => {
    // listar() faz this.http.get(...) e a resposta chega na hora
    console.log('HTTP: chegou');
    this.documentos = docs;
  });

  interval(1000).subscribe(n => {
    console.log('tick ' + n);
  });
}

